BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_spec'
S=['拉丁语 sculpere；分词词干 sculpt-','雕刻、刻出形状']
SCULPTURE=[S,['拉丁语 sculptura；古法语 sculpture','雕刻艺术'],['中古英语 sculpture → 现代英语 sculpture','雕塑艺术；一件雕塑；后来也转作动词']]
SCULPT=[S,['法语 sculpter → 英语 sculpt','雕刻、塑造；英语后来也把它理解为 sculptor、sculpture 的逆构词']]
W=[
E('sculpture','英 /ˈskʌlptʃə/；美 /ˈskʌlptʃər/','雕塑；雕塑作品','既可以说立体造型这门艺术，也可以数出一件件作品。','来自拉丁 sculptura，联系 sculpere 的分词词干 sculpt-；法语 sculpture 也是借入路线。英语名词早于现代动词 sculpt，不能倒写成先有 sculpt 再加 -ure。',SCULPTURE,'study sculpture 是学习雕塑这门艺术，不可数；a sculpture 是一件雕塑，可以数。词源起于雕刻，但现代雕塑还能塑泥、铸金属、组合材料，不限于从石头上凿掉东西。','study sculpture；a bronze sculpture；an exhibition of sculpture；three sculptures。','statue 多指人物或动物的塑像；sculpture 范围更广，也能是抽象形状。不是所有 sculpture 都像一个人。',('A curved steel sculpture stands outside the library.','图书馆外立着一件弯曲的钢制雕塑。'),('She studied sculpture before moving into furniture design.','她转做家具设计之前学的是雕塑。'),sources=['https://www.etymonline.com/word/sculpture','https://www.oxfordlearnersdictionaries.com/definition/english/sculpture','https://en.wiktionary.org/wiki/sculpture']),
E('sculptor','英 /ˈskʌlptə/；美 /ˈskʌlptər/','雕塑家；雕刻者','把立体材料做成作品的人。','借拉丁 sculptor“雕刻者”，由 sculpt- + 表人的 -or 构成。现代可按 sculpt + -or 记，但英语 sculptor 出现早于 sculpt，真正历史并非英语动词加后缀。',[S,['拉丁语 sculptor → 英语 sculptor','雕刻、塑造作品的人']],'sculptor 的材料不只石头：泥、木、金属甚至回收零件都可以。职业名称也不限定性别；说 a sculptor，重点是这个人以立体形式创作。','a sculptor working in bronze；a stone sculptor；commission a sculptor。','sculptor 指创作者，sculpture 指作品或艺术门类。不要把结尾 -or 和 -ure 当成可互换的拼写。',('The sculptor made a small clay model before casting the final piece.','这位雕塑家先做了一个小泥模，再铸造最终作品。'),('A local sculptor designed the memorial in the town square.','镇广场上的纪念雕塑由一位当地雕塑家设计。'),sources=['https://www.etymonline.com/word/sculptor','https://www.oxfordlearnersdictionaries.com/definition/english/sculptor']),
E('sculptural','英美 /ˈskʌlptʃərəl/','雕塑的；具有雕塑感的','既能说与雕塑有关，也能说某样东西的体量和线条很像雕塑。','英语 sculpture 去词尾 e 加 -al，形成形容词。这里是真正的英语派生，不必再假设一个独立古代借词。',SCULPTURE+[['英语 sculpture + -al → sculptural','与雕塑有关；像雕塑的']],'sculptural techniques 是雕塑技法；a sculptural staircase 则可能只是楼梯形体很鲜明，让人像看雕塑一样关注它的转折、曲面与体量。后一种用法不要求东西真被艺术家雕过。','sculptural form；sculptural decoration；sculptural techniques；a sculptural quality。','sculptural 描写关系或视觉特点；sculpted 往往突出被塑造出来的结果。一个天然树干也可能有 sculptural form。',('The folded roof gives the building a sculptural quality.','折叠般的屋顶让这座建筑有了雕塑感。'),('The course introduces several sculptural techniques.','这门课介绍几种雕塑技法。'),sources=['https://www.etymonline.com/word/sculptural','https://www.oxfordlearnersdictionaries.com/definition/english/sculptural']),
E('sculpt','英美 /skʌlpt/','雕刻；塑造','通过削、捏、塑等动作，让材料形成明确的立体形状。','借法语 sculpter，接拉丁 sculpere、sculpt-。英语后来也把它看成从 sculptor 或 sculpture 去掉尾部得到的动词；这不等于更早的两个名词由英语 sculpt 派生。',SCULPT,'艺术家能 sculpt a face in clay，海风也能 sculpt the rocks。后一例把自然力量当成雕塑家，突出表面和轮廓经过长期作用慢慢成形。','sculpt a figure；sculpt something from stone；sculpt in clay；be sculpted by wind。','carve 更突出切、刻、削；sculpt 更突出造出立体形体，也可以通过加泥来塑造。雕塑的动作不必总是减去材料。',('She used a wooden tool to sculpt the folds in the clay coat.','她用木制工具塑出泥像外衣上的褶皱。'),('Wind and rain slowly sculpt the sandstone cliffs.','风雨慢慢塑造着砂岩崖壁的轮廓。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/sculpt','https://www.etymonline.com/word/sculpt','https://www.merriam-webster.com/dictionary/sculpt']),
E('sculptured','英 /ˈskʌlptʃəd/；美 /ˈskʌlptʃərd/','雕刻成的；轮廓鲜明的','强调已经成形，或看起来像经过细心雕琢。','英语动词 sculpture + -ed；写作 sculptured。它与 sculpt + -ed 的 sculpted 是两套词形，前者保留 sculpture 的 /tʃ/ 音。',SCULPTURE+[['英语 sculpture 作动词 → sculptured','雕塑成的；像被精心雕刻的']],'a sculptured panel 是有雕刻造型的板面；sculptured features 则常是在赞叹人的五官轮廓鲜明。第二种说法是形象比喻，不能据此推断真实做过雕刻或手术。','a sculptured panel；sculptured figures；sculptured features。','sculptured 和 sculpted 常有近似意思，但读音不同：前者中间有 /tʃ/，后者是 /pt/ 后接 /ɪd/。不要只看意思而漏读词形。',('The doorway is framed by sculptured stone panels.','门口两侧和上方装饰着雕刻石板。'),('Side lighting emphasized the actor’s sculptured features.','侧光突出了那位演员轮廓鲜明的五官。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/sculptured','https://www.etymonline.com/word/sculpt']),
E('sculpted','英美 /ˈskʌlptɪd/','雕塑成的；塑造出鲜明轮廓的','把注意力放在塑造完成后的形状。','英语 sculpt + -ed，既是过去式、过去分词，也可作形容词。/t/ 后的 -ed 读 /ɪd/。',SCULPT+[['英语 sculpted','已经雕刻、塑造；形成鲜明轮廓的']],'a sculpted figure 是雕塑成的形象；a sculpted landscape 可以描写地貌经过自然作用后留下的起伏和纹理。它也常修饰产品线条，像车身被仔细塑造过一样。','a sculpted figure；sculpted surfaces；sculpted from wood；sculpted by erosion。','sculpted 表示动作结果或外观，不保证手工制作。一件数字模型、机器加工的部件，也能拥有 sculpted surfaces。',('The small bird was sculpted from a single piece of wood.','这只小鸟是用一整块木头雕出来的。'),('The car’s sculpted sides catch the afternoon light.','汽车富有立体线条的侧面映着午后的光。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/sculpt','https://www.merriam-webster.com/dictionary/sculpted']),
E('sculpting','英美 /ˈskʌlptɪŋ/','雕刻、塑造的过程；正在雕塑','将做出立体形状这件事作为过程来谈。','英语 sculpt + -ing，可构成进行时，也可把动作变成名词性活动。',SCULPT+[['英语 sculpting','正在雕塑；雕塑活动与过程']],'She is sculpting a mask 中，sculpting 和 is 一起表示正在做；digital sculpting 则把整套数字塑形过程当作活动名称。电脑里的材料虽是虚拟的，仍沿用用手和工具塑造形体的思路。','clay sculpting；digital sculpting；sculpting tools；be sculpting a figure。','sculpting 突出创作活动，sculpture 可以是艺术门类或已完成的作品。说 two sculptures 是两件作品，不说 two sculptings 来代替。',('He spent the afternoon sculpting a mask from soft clay.','他整个下午都在用软陶泥塑一张面具。'),('The workshop introduces digital sculpting to beginners.','这个工作坊向初学者介绍数字雕塑。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/sculpt','https://en.wiktionary.org/wiki/sculpting'])
]
m=json.loads((BASE/'.cache/batch200/rewrite_spec.json').read_text());r=next(r for r in m['roots']if r['id']=='C1290');family=r['family'];keep={w['word']for w in W}
